import { GoogleGenerativeAI } from "@google/generative-ai";
import { NextResponse } from "next/server";

/**
 * Helper to extract JSON from AI response that might be wrapped in Markdown code blocks
 */
function extractJSON(text: string): string {
  // Try markdown blocks first
  const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
  if (jsonMatch) return jsonMatch[1].trim();

  // Falling back to searching for boundaries if no code blocks exist
  const firstBracket = text.indexOf('[');
  const firstBrace = text.indexOf('{');

  let start = -1;
  if (firstBracket !== -1 && (firstBrace === -1 || firstBracket < firstBrace)) {
    start = firstBracket;
  } else if (firstBrace !== -1) {
    start = firstBrace;
  }

  if (start !== -1) {
    const lastBracket = text.lastIndexOf(']');
    const lastBrace = text.lastIndexOf('}');
    const end = Math.max(lastBracket, lastBrace);

    if (end > start) {
      return text.substring(start, end + 1).trim();
    }
  }

  const cleaned = text.trim();
  if (cleaned.toLowerCase() === "undefined" || !cleaned) {
    return "[]";
  }

  return cleaned;
}

export async function POST(request: Request) {
  try {
    const apiKey = process.env.GEMINI_API_KEY || "";
    if (!apiKey) {
      console.error("GEMINI_API_KEY is missing");
      return NextResponse.json({ error: "Configuration error: API key missing" }, { status: 500 });
    }

    const genAI = new GoogleGenerativeAI(apiKey);

    const contentType = request.headers.get("content-type") || "";
    let action = "";
    let content = "";
    let targetRole = "";
    let userSkills: string[] = [];

    // CRITICAL: Polyfill for DOMMatrix/DOMPoint which are missing in Node.js
    // but sometimes required by pdf.js (via pdf-parse) for complex PDFs.
    if (typeof (global as any).DOMMatrix === "undefined") {
      (global as any).DOMMatrix = class DOMMatrix {
        constructor() {}
        static fromFloat32Array() { return new DOMMatrix(); }
        static fromFloat64Array() { return new DOMMatrix(); }
      };
    }
    if (typeof (global as any).DOMPoint === "undefined") {
      (global as any).DOMPoint = class DOMPoint {
        constructor() {}
      };
    }

    if (contentType.includes("multipart/form-data")) {
      const formData = await request.formData();
      action = (formData.get("action") as string) || "extract-skills";
      const file = formData.get("file") as File;

      console.log(`Analyzing file: ${file?.name}, type: ${file?.type}, size: ${file?.size}`);

      if (file) {
        const bytes = await file.arrayBuffer();
        const buffer = Buffer.from(bytes);

        // More resilient PDF check
        const isPdf = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");

        if (isPdf) {
          try {
            console.log("Starting PDF extraction with polyfills...");
            const pdf = require("pdf-parse");
            // Disable canvas to avoid further browser API issues
            const options = {
              pagerender: (pageData: any) => {
                return pageData.getTextContent().then((textContent: any) => {
                  return textContent.items.map((item: any) => item.str).join(' ');
                });
              }
            };
            const data = await pdf(buffer, options);
            content = data.text;
            console.log(`PDF extracted successfully: ${content.length} characters`);
          } catch (pdfError: any) {
            console.error("PDF Parsing Error:", pdfError);
            return NextResponse.json({ 
              error: "Failed to parse PDF resume", 
              details: pdfError.message || "Unknown PDF error"
            }, { status: 500 });
          }
        } else {
          content = buffer.toString("utf8");
          console.log(`Text-based file read: ${content.length} characters`);
        }
      } else {
        content = (formData.get("content") as string) || "";
        console.log(`Direct content analysis: ${content.length} characters`);
      }

      targetRole = (formData.get("targetRole") as string) || "";
      const skillsStr = formData.get("userSkills") as string;
      userSkills = skillsStr ? JSON.parse(skillsStr) : [];

    } else {
      const body = await request.json();
      action = body.action;
      content = body.content;
      targetRole = body.targetRole;
      userSkills = body.userSkills || [];
    }

    if (!content && action === "extract-skills") {
      return NextResponse.json({ result: "[]" });
    }

    // Use the latest flash model which is more stable across API versions
    const modelName = "gemini-1.5-flash-latest";
    const model = genAI.getGenerativeModel({ model: modelName });

    let prompt = "";
    if (action === "extract-skills") {
      prompt = `You are a high-level technical recruiter and AI analyst. 
      Analyze the following content (resume, bio, or profile) and interpret the core technical and soft skills. 

      Instructions:
      1. Extract specific technical skills (languages, frameworks, tools).
      2. Interpret soft skills based on experience and accomplishments.
      3. Identify implied skills from described projects.
      4. Return ONLY a JSON array of strings. 
      5. If no clear skills are found, return [].

      Content: ${content}`;
    } else if (action === "gap-analysis") {
      prompt = `As an expert career coach, compare these user skills: ${userSkills.join(", ")} 
      against the requirements for a ${targetRole}. 
      Identify:
      1. Matching skills (that the user has).
      2. Missing skills (required for the role but missing/weak in the user profile).
      Return ONLY a JSON object with 'matching' and 'missing' arrays.`;
    } else if (action === "generate-cover-letter") {
      prompt = `Generate a professional, high-impact cover letter for the role of ${targetRole} based on these skills: ${userSkills.join(", ")}. Keep it under 300 words. Return plain text.`;
    }

    let text = "";
    try {
      const result = await model.generateContent(prompt);
      const response = await result.response;
      text = response.text();
    } catch (err: any) {
      console.error("AI Generation failed:", err);
      // Fallback if blocked
      if (err.message?.includes("safety") || !text) {
        return NextResponse.json({ 
          error: "AI analysis was blocked by safety filters or returned an empty response.",
        }, { status: 400 });
      }
      throw err;
    }

    const finalResult = (action === "extract-skills" || action === "gap-analysis") 
      ? extractJSON(text) 
      : text;

    return NextResponse.json({ result: finalResult });
  } catch (error: any) {
    console.error("AI Analysis Error:", error);
    return NextResponse.json({ 
      error: "Analysis failed", 
      details: error.message || String(error) 
    }, { status: 500 });
  }
}

import { NextResponse } from "next/server";

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const query = searchParams.get("q") || "";
  const location = searchParams.get("location") || "";
  const remote = searchParams.get("remote") === "true";

  // Using Adzuna API as it's free/reliable for demos
  // App ID and Key should be in env, using placeholders for now
  const APP_ID = process.env.ADZUNA_APP_ID || "test";
  const APP_KEY = process.env.ADZUNA_APP_KEY || "test";

  try {
    console.log(`Searching for ${query} in ${location} (remote: ${remote})`);

    // Mock results if keys are missing
    if (APP_ID === "test" || APP_KEY === "test") {
      console.log("Using mock job data (API keys missing)");
      return NextResponse.json({
        results: [
          {
            id: "mock-1",
            title: `${query || "Data Scientist"}`,
            company: "Tech Intelligence Inc.",
            location: location || "Remote",
            salary: "₹1,200,000 - ₹2,400,000",
            type: "Full-time",
            isRemote: true,
            description: "Exciting opportunity to work on AI and large language models.",
            url: "#",
            skills: ["React", "TypeScript", "Next.js"]
          },
          {
            id: "mock-2",
            title: "Senior Software Engineer",
            company: "Global Digital Systems",
            location: "Bangalore",
            salary: "₹1,800,000 - ₹3,600,000",
            type: "Contract",
            isRemote: false,
            description: "Leading the development of a state-of-the-art career accelerator platform.",
            url: "#",
            skills: ["Python", "FastAPI", "Docker"]
          }
        ]
      });
    }

    const url = `https://api.adzuna.com/v1/api/jobs/in/search/1?app_id=${APP_ID}&app_key=${APP_KEY}&what=${encodeURIComponent(query)}&where=${encodeURIComponent(location)}${remote ? "&remote=1" : ""}&content-type=application/json`;

    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`External API returned ${response.status}`);
    }
    const data = await response.json();

    return NextResponse.json({
      results: data.results?.map((job: any) => ({
        id: job.id,
        title: job.title,
        company: job.company.display_name,
        location: job.location.display_name,
        salary: job.salary_min ? `₹${job.salary_min.toLocaleString()} - ₹${job.salary_max?.toLocaleString()}` : "Competitive",
        type: job.contract_type || "Full-time",
        isRemote: !!job.location.area?.find((a: string) => a.toLowerCase() === 'remote'),
        description: job.description,
        url: job.redirect_url,
        created: job.created,
        skills: [] 
      })) || []
    });
  } catch (error: any) {
    console.error("Job Search API Error:", error);
    return NextResponse.json({ error: "Failed to fetch jobs", details: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { GoogleGenerativeAI } from "@google/generative-ai";

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY!);

export async function POST(req: NextRequest) {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const { action, title, content } = await req.json();

    if (!action || !content) {
      return NextResponse.json({ error: "Missing required fields" }, { status: 400 });
    }

    const models = ["gemini-1.5-flash-latest", "gemini-1.5-flash", "gemini-2.0-flash", "gemini-flash-latest"];
    let lastError: any;
    let text = "";
    let success = false;

    for (const modelName of models) {
      try {
        console.log(`[AI Notes] Attempting ${modelName}...`);
        const model = genAI.getGenerativeModel({ model: modelName });


    let prompt = "";
    if (action === "suggest_title") {
      prompt = `Based on the following note content, suggest a concise and professional title (max 6 words). Return ONLY the title text, nothing else.\n\nContent:\n${content}`;
    } else if (action === "summarize") {
      prompt = `Analyze the following note content and generate a 3-5 line summary. Focus on the main points and actionable insights. Return ONLY the summary text.\n\nContent:\n${content}`;
    } else if (action === "bullet_points") {
      prompt = `Transform the following note content into a clear, structured list of bullet points. Simplify and organize the information. Return ONLY the bullet points as a markdown list.\n\nContent:\n${content}`;
    } else {
      return NextResponse.json({ error: "Invalid action" }, { status: 400 });
    }

        const result = await model.generateContent(prompt);
        text = result.response.text().trim();
        success = true;
        console.log(`[AI Notes] Success with ${modelName}`);
        break;
      } catch (err: any) {
        lastError = err;
        console.warn(`[AI Notes] Model ${modelName} failed:`, err.message);
        continue;
      }
    }

    if (!success) {
      throw lastError || new Error("All models failed to generate content");
    }


    return NextResponse.json({ result: text });
  } catch (err: any) {
    console.error("AI Action API error:", err);
    return NextResponse.json(
      { error: `AI process failed: ${err.message}` },
      { status: 500 }
    );
  }
}

"use client";

import React, { useState, useEffect } from "react";
import { 
  Briefcase, 
  Search, 
  Sparkles, 
  TrendingUp, 
  Upload, 
  X, 
  MapPin, 
  Clock, 
  DollarSign, 
  ExternalLink, 
  Bookmark,
  ChevronRight,
  Filter
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";
import { toast } from "react-hot-toast";

interface Job {
  id: string;
  title: string;
  company: string;
  location: string;
  salary: string;
  type: string;
  isRemote: boolean;
  description: string;
  url: string;
  skills: string[];
}

export default function JobSearchClient({ user }: { user: any }) {
  const [query, setQuery] = useState("");
  const [location, setLocation] = useState("");
  const [isRemote, setIsRemote] = useState(false);
  const [jobs, setJobs] = useState<Job[]>([]);
  const [loading, setLoading] = useState(false);
  const [extractedSkills, setExtractedSkills] = useState<string[]>([]);
  const [targetRole, setTargetRole] = useState("");
  const [profileText, setProfileText] = useState("");
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isGeneratingCoverLetter, setIsGeneratingCoverLetter] = useState(false);
  const [showAnalysis, setShowAnalysis] = useState(false);
  const [activeCoverLetter, setActiveCoverLetter] = useState<string | null>(null);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    console.log("Searching for:", { query, location, isRemote });
    setLoading(true);
    try {
      const res = await fetch(`/api/jobs/search?q=${encodeURIComponent(query)}&location=${encodeURIComponent(location)}&remote=${isRemote}`);
      if (!res.ok) throw new Error(`Search failed: ${res.status}`);
      const data = await res.json();
      console.log("Search results:", data.results);
      setJobs(data.results || []);
      if ((data.results || []).length === 0) {
        toast.error("No jobs found matching your criteria.");
      } else {
        toast.success(`Found ${data.results.length} jobs!`);
      }
    } catch (err) {
      console.error("Search Error:", err);
      toast.error("Failed to connect to job search service.");
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyzeProfile = async (file?: File) => {
    if (!file && !profileText.trim()) {
      toast.error("Please provide a resume or profile text");
      return;
    }

    console.log("Analyzing profile/file:", file?.name || "Text content");
    setIsAnalyzing(true);
    const loadingToast = toast.loading(file ? `Analyzing ${file.name}...` : "Analyzing profile...");

    try {
      const formData = new FormData();
      formData.append("action", "extract-skills");

      if (file) {
        formData.append("file", file);
      } else {
        formData.append("content", profileText);
      }

      const res = await fetch("/api/jobs/analyze", {
        method: "POST",
        body: formData
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.details || errorData.error || "Analysis failed");
      }

      const data = await res.json();

      // Safe parsing with fallback
      let skills: string[] = [];
      try {
        skills = typeof data.result === "string" ? JSON.parse(data.result) : data.result;
        if (!Array.isArray(skills)) skills = [];
      } catch (e) {
        console.error("Failed to parse skills:", e);
        skills = [];
      }

      if (skills.length === 0) {
        toast.error("No skills identified. Please try a different file.");
      } else {
        setExtractedSkills(skills);
        setQuery(skills.slice(0, 3).join(", "));
        setShowAnalysis(true);
        toast.success(`Extracted ${skills.length} skills!`);
      }
    } catch (err) {
      console.error(err);
      toast.error("An error occurred during analysis");
    } finally {
      setIsAnalyzing(false);
      toast.dismiss(loadingToast);
    }
  };

  return (
    <main className="max-w-6xl mx-auto px-6 py-24">
      {/* Hero Section */}
      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="mb-16"
      >
        <div className="flex items-center gap-3 mb-6">
          <div className="w-12 h-12 rounded-2xl bg-foreground/5 border border-border flex items-center justify-center">
            <Briefcase className="w-6 h-6 text-foreground/40" />
          </div>
          <span className="text-[10px] text-muted-foreground font-black uppercase tracking-[0.4em]">Career Accelerator</span>
        </div>
        <h1 className="text-5xl md:text-7xl font-black tracking-tight mb-6">
          AI <span className="text-muted-foreground/30">Job Search</span>.
        </h1>
        <p className="text-xl text-muted-foreground max-w-2xl font-medium leading-relaxed italic">
          "The future belongs to those who learn more skills and combine them in creative ways."
        </p>
      </motion.div>

      {/* Advanced Search Bar */}
      <section className="mb-20">
        <div className="bg-card border-2 border-border rounded-[3rem] p-4 shadow-2xl relative overflow-hidden group focus-within:border-foreground/20 transition-all">
          <form onSubmit={handleSearch} className="flex flex-col md:flex-row items-center gap-4 relative z-10">
            <div className="flex-1 flex items-center px-4 w-full">
              <Search className="w-6 h-6 text-muted-foreground mr-4" />
              <input 
                type="text" 
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Skills, Roles, or Companies..." 
                className="w-full bg-transparent border-none text-xl font-bold py-4 focus:ring-0 outline-none placeholder:text-muted-foreground/30"
                suppressHydrationWarning
              />
            </div>

            <div className="h-8 w-[2px] bg-border hidden md:block" />

            <div className="flex-1 flex items-center px-4 w-full">
              <MapPin className="w-6 h-6 text-muted-foreground mr-4" />
              <input 
                type="text" 
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                placeholder="Location or 'Remote'..." 
                className="w-full bg-transparent border-none text-xl font-bold py-4 focus:ring-0 outline-none placeholder:text-muted-foreground/30"
                suppressHydrationWarning
              />
            </div>

              <button 
                type="submit"
                suppressHydrationWarning
                className="bg-foreground text-background px-10 py-5 rounded-full font-black uppercase tracking-widest hover:scale-105 transition-transform flex items-center gap-2 group/btn"
              >
                <span suppressHydrationWarning>Search</span>
                <ChevronRight className="w-5 h-5 group-hover/btn:translate-x-1 transition-transform" />
              </button>
          </form>

          {/* Quick Filters */}
          <div className="flex items-center gap-6 mt-4 px-6 pb-2">
            <label className="flex items-center gap-2 cursor-pointer group/toggle">
              <input 
                type="checkbox" 
                checked={isRemote}
                onChange={() => setIsRemote(!isRemote)}
                className="hidden" 
              />
              <div className={cn(
                "w-10 h-6 rounded-full transition-colors relative",
                isRemote ? "bg-foreground" : "bg-foreground/10"
              )}>
                <motion.div 
                  animate={{ x: isRemote ? 18 : 3 }}
                  className="w-4 h-4 bg-background rounded-full absolute top-1"
                />
              </div>
              <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground group-hover/toggle:text-foreground">Remote Only</span>
            </label>

            <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-muted-foreground hover:text-foreground transition-colors cursor-pointer relative overflow-hidden group/upload">
              <Upload className="w-3.5 h-3.5" />
              <span suppressHydrationWarning>Upload Resume</span>
              <input 
                type="file" 
                accept=".txt,.pdf,.docx"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    handleAnalyzeProfile(file);
                  }
                }}
                className="absolute inset-0 opacity-0 cursor-pointer"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Results / Empty State */}
      <div className="space-y-12">
        {loading ? (
          <div className="grid gap-6">
            {[1, 2, 3].map(i => (
              <div key={i} className="h-48 bg-foreground/5 rounded-3xl animate-pulse" />
            ))}
          </div>
        ) : jobs.length > 0 ? (
          <div className="grid gap-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xs font-black uppercase tracking-[0.4em] text-muted-foreground/60">{jobs.length} Opportunities Found</h2>
              <div className="flex gap-2">
                <button className="p-2 rounded-xl bg-foreground/5 border border-border hover:border-foreground/20 transition-all">
                  <Filter className="w-4 h-4" />
                </button>
              </div>
            </div>
            {jobs.map((job) => (
              <JobCard key={job.id} job={job} />
            ))}
          </div>
        ) : (
          <div className="text-center py-32 border-2 border-dashed border-border rounded-[3rem]">
            <p className="text-muted-foreground font-black uppercase tracking-[0.4em] opacity-40">Awaiting Search Initialization</p>
            <p className="text-sm font-medium mt-4 text-muted-foreground/60">Search by skills to explore global opportunities.</p>
          </div>
        )}
      </div>

      {/* Side Panels (Industry Insights, Skill Gaps etc - placeholders) */}
      <div className="grid md:grid-cols-3 gap-8 mt-24">
        <div className="col-span-2 bg-foreground/5 border border-border rounded-[2.5rem] p-10">
          <h3 className="text-xl font-black mb-6 uppercase tracking-wider">AI Skill Recommender</h3>
          <p className="text-muted-foreground font-medium mb-8">Paste your latest project summary or LinkedIn bio to see where you fit best.</p>
          <textarea 
            value={profileText}
            onChange={(e) => setProfileText(e.target.value)}
            className="w-full bg-background border border-border rounded-2xl p-6 min-h-[150px] outline-none focus:border-foreground/40 transition-all text-sm font-medium"
            placeholder="Experience with React, Node.js and building high-scale intelligence systems..."
          />
          <button 
            onClick={() => handleAnalyzeProfile()}
            disabled={isAnalyzing}
            suppressHydrationWarning
            className="mt-6 bg-foreground text-background px-8 py-4 rounded-full font-black text-xs uppercase tracking-widest hover:invert transition-all disabled:opacity-50"
          >
            <span suppressHydrationWarning>{isAnalyzing ? "Analyzing..." : "Analyze Profile"}</span>
          </button>

          <AnimatePresence>
            {showAnalysis && (
              <motion.div 
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                className="mt-8 pt-8 border-t border-border"
              >
                <h4 className="text-xs font-black uppercase tracking-widest mb-4">AI Interpreted Skills</h4>
                <div className="flex flex-wrap gap-2 mb-6">
                  {extractedSkills.map(s => (
                    <span key={s} className="bg-foreground text-background px-3 py-1 rounded-lg text-[10px] font-bold">
                      {s}
                    </span>
                  ))}
                </div>
                <button 
                  onClick={() => { handleSearch(); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
                  className="text-xs font-black uppercase tracking-widest flex items-center gap-2 hover:translate-x-1 transition-transform"
                >
                  Search Jobs for These Skills <ChevronRight className="w-4 h-4" />
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <div className="bg-card border-2 border-border rounded-[2.5rem] p-8">
          <div className="flex items-center gap-3 mb-8">
            <TrendingUp className="w-5 h-5 text-foreground" />
            <h3 className="text-xs font-black uppercase tracking-widest">Industry Trends</h3>
          </div>
          <div className="space-y-6">
            {[
              { skill: "AI Engineering", trend: "+124%" },
              { skill: "Cloud Security", trend: "+82%" },
              { skill: "Next.js 15", trend: "+45%" }
            ].map(s => (
              <div key={s.skill} className="flex justify-between items-center pb-4 border-b border-border/50">
                <span className="text-xs font-bold">{s.skill}</span>
                <span className="text-[10px] font-black text-green-500">{s.trend}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </main>
  );
}

function JobCard({ job }: { job: Job }) {
  return (
    <motion.div 
      whileHover={{ y: -5 }}
      className="bg-card border-2 border-border rounded-[2.5rem] p-8 flex flex-col md:flex-row gap-8 hover:border-foreground/20 transition-all shadow-xl hover:shadow-2xl relative group"
    >
