"use client";

import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Placeholder from '@tiptap/extension-placeholder';
import Link from '@tiptap/extension-link';
import { Underline } from '@tiptap/extension-underline';
import { Highlight } from '@tiptap/extension-highlight';
import { TextStyle } from '@tiptap/extension-text-style';
import { FontFamily } from '@tiptap/extension-font-family';
import { 
    ChevronLeft, 
    Save, 
    Sparkles, 
    Bold, 
    Italic, 
    Underline as UnderlineIcon,
    List, 
    ListOrdered,
    Code, 
    Heading1,
    Heading2,
    Heading3,
    CheckCircle2,
    Loader2,
    Type,
    LayoutList,
    AlignLeft,
    Download,
    Highlighter,
    CaseSensitive,
    ChevronDown,
    FileText,
    FileCode,
} from 'lucide-react';
import React, { useEffect, useState, useRef } from 'react';
import { formatDate } from '@/lib/utils';
import CharacterCount from '@tiptap/extension-character-count';
import toast from 'react-hot-toast';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface Note {
    id: string;
    user_id: string;
    folder_id: string | null;
    title: string;
    content: Record<string, unknown>; // Content is JSONB from Tiptap
    is_pinned: boolean;
    is_favorite: boolean;
    last_edited_at: string;
    created_at: string;
    updated_at: string;
}

interface NoteEditorProps {
    note: Note;
    onSave: (updates: Partial<Note>) => void;
    onBack: () => void;
}

export default function NoteEditor({ note, onSave, onBack }: NoteEditorProps) {
    const [title, setTitle] = useState(note.title === "Untitled Note" ? "" : (note.title || ""));
    const [isSaving, setIsSaving] = useState(false);
    const [lastSaved, setLastSaved] = useState<Date | null>(null);
    const [showAiMenu, setShowAiMenu] = useState(false);
    const [showDownloadMenu, setShowDownloadMenu] = useState(false);
    const [showHeadingMenu, setShowHeadingMenu] = useState(false);
    const [showHighlightMenu, setShowHighlightMenu] = useState(false);
    const [showFontMenu, setShowFontMenu] = useState(false);
    const [isAiProcessing, setIsAiProcessing] = useState(false);

    const aiMenuRef = useRef<HTMLDivElement>(null);
    const downloadMenuRef = useRef<HTMLDivElement>(null);
    const headingMenuRef = useRef<HTMLDivElement>(null);
    const highlightMenuRef = useRef<HTMLDivElement>(null);
    const fontMenuRef = useRef<HTMLDivElement>(null);
    const editorContainerRef = useRef<HTMLDivElement>(null);

    const editor = useEditor({
        immediatelyRender: false,
        extensions: [
            StarterKit,
            Placeholder.configure({
                placeholder: 'Start writing your brilliance...',
            }),
            Link.configure({
                openOnClick: false,
            }),
            Underline,
            Highlight.configure({ multicolor: true }),
            TextStyle,
            FontFamily,
            CharacterCount,
        ],
        content: note.content,
        editorProps: {
            attributes: {
                class: 'prose max-w-none focus:outline-none min-h-[500px] pb-32 font-clean text-black',
            },
        },
    });

    // Auto-focus on load
    useEffect(() => {
        if (editor && !editor.isFocused) {
            editor.commands.focus('end');
        }
    }, [editor]);

    // Handle clicks outside menus
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            const refs = [aiMenuRef, downloadMenuRef, headingMenuRef, highlightMenuRef, fontMenuRef];
            const clickedInside = refs.some(ref => ref.current?.contains(event.target as Node));
            if (!clickedInside) {
                setShowAiMenu(false);
                setShowDownloadMenu(false);
                setShowHeadingMenu(false);
                setShowHighlightMenu(false);
                setShowFontMenu(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const handleManualSave = async () => {
        setIsSaving(true);
        try {
            await onSave({
                title: title.trim() || "Untitled Note",
                content: editor?.getJSON(),
            });
            setLastSaved(new Date());
            toast.success("Intelligence secured.");
            setTimeout(onBack, 1000);
        } catch (error) {
            toast.error("Failed to save intelligence.");
        } finally {
            setIsSaving(false);
        }
    };

    const handleDownloadPdf = async () => {
        if (!editorContainerRef.current) return;
        setShowDownloadMenu(false);
        const loadingToast = toast.loading("Synthesizing PDF...");

        try {
            const canvas = await html2canvas(editorContainerRef.current, {
                scale: 2,
                useCORS: true,
                backgroundColor: "#000000",
            });

            const imgData = canvas.toDataURL('image/png');
            const pdf = new jsPDF('p', 'mm', 'a4');
            const imgProps = pdf.getImageProperties(imgData);
            const pdfWidth = pdf.internal.pageSize.getWidth();
            const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

            pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
            pdf.save(`${title.replace(/\s+/g, '_')}.pdf`);
            toast.success("PDF Downloaded", { id: loadingToast });
        } catch (err) {
            toast.error("PDF Synthesis Failed", { id: loadingToast });
        }
    };

    const handleDownloadTxt = () => {
        if (!editor) return;
        setShowDownloadMenu(false);
        const text = `${title}\n\n${editor.getText()}`;
        const blob = new Blob([text], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${title.replace(/\s+/g, '_')}.txt`;
        a.click();
        URL.revokeObjectURL(url);
        toast.success("TXT Downloaded");
    };

    const handleAiAction = async (action: 'suggest_title' | 'summarize' | 'bullet_points') => {
        if (!editor) return;
        setIsAiProcessing(true);
        setShowAiMenu(false);

        const content = editor.getText();
        if (!content.trim() && action !== 'suggest_title') {
            toast.error("Please add some content first.");
            setIsAiProcessing(false);
            return;
        }

        try {
            const response = await fetch('/api/notes/ai', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action, content, title }),
            });

            const data = await response.json();
            if (data.error) throw new Error(data.error);

            if (action === 'suggest_title') {
                setTitle(data.result);
                toast.success("Intelligence title optimized.");
            } else if (action === 'summarize') {
                editor.chain().focus().insertContentAt(0, `<div class="bg-foreground/5 p-4 rounded-xl border border-border/50 mb-6 italic text-muted-foreground">Summary: ${data.result}</div><p></p>`).run();
                toast.success("Intelligence summarized.");
            } else if (action === 'bullet_points') {
                editor.chain().focus().setContent(data.result).run();
                toast.success("Content structured into directives.");
            }
        } catch (error: any) {
            toast.error(error.message || "AI processing failed");
        } finally {
            setIsAiProcessing(false);
        }
    };

    if (!editor) return null;

    return (
        <div className="flex-1 flex flex-col h-full bg-white overflow-hidden selection:bg-black selection:text-white text-black">
            {/* Optimized Toolbar Layout: Back | Tools | AI | Save */}
            <div className="border-b border-gray-100 px-6 py-2 flex items-center justify-between bg-white backdrop-blur-xl z-30 sticky top-0">
                <div className="flex items-center gap-1">
                    <button 
                        onClick={onBack}
                        className="p-2 hover:bg-gray-50 rounded-xl transition-all group mr-2"
                        title="Back to Dashboard"
                    >
                        <ChevronLeft className="w-5 h-5 text-gray-400 group-hover:text-black" />
                    </button>

                    <div className="flex items-center gap-1 bg-gray-50 p-1 rounded-2xl border border-gray-100">
                         {/* Headings Dropdown */}
                        <div className="relative" ref={headingMenuRef}>
                            <ToolbarButton 
                                onClick={() => setShowHeadingMenu(!showHeadingMenu)} 
                                active={editor.isActive('heading') || editor.isActive('paragraph')}
                                icon={
                                    editor.isActive('heading', { level: 1 }) ? Heading1 :
                                    editor.isActive('heading', { level: 2 }) ? Heading2 :
                                    editor.isActive('heading', { level: 3 }) ? Heading3 :
                                    Type
                                } 
                                hasDropdown
                            />
                            {showHeadingMenu && (
                                <div className="absolute left-0 mt-2 w-48 bg-card border border-border rounded-xl shadow-2xl z-50 p-1">
                                    <DropdownItem onClick={() => { editor.chain().focus().setParagraph().run(); setShowHeadingMenu(false); }} icon={Type} label="Normal Text" active={editor.isActive('paragraph')} />
                                    <div className="h-px bg-border/20 my-1 mx-2" />
                                    <DropdownItem onClick={() => { editor.chain().focus().toggleHeading({ level: 1 }).run(); setShowHeadingMenu(false); }} icon={Heading1} label="Main Heading" active={editor.isActive('heading', { level: 1 })} />
                                    <DropdownItem onClick={() => { editor.chain().focus().toggleHeading({ level: 2 }).run(); setShowHeadingMenu(false); }} icon={Heading2} label="Sub Heading" active={editor.isActive('heading', { level: 2 })} />
                                    <DropdownItem onClick={() => { editor.chain().focus().toggleHeading({ level: 3 }).run(); setShowHeadingMenu(false); }} icon={Heading3} label="Section Heading" active={editor.isActive('heading', { level: 3 })} />
                                </div>
                            )}
                        </div>

                        <div className="w-px h-4 bg-border/20 mx-1" />

                        <ToolbarButton onClick={() => editor.chain().focus().toggleBold().run()} active={editor.isActive('bold')} icon={Bold} />
                        <ToolbarButton onClick={() => editor.chain().focus().toggleItalic().run()} active={editor.isActive('italic')} icon={Italic} />
                        <ToolbarButton onClick={() => editor.chain().focus().toggleUnderline().run()} active={editor.isActive('underline')} icon={UnderlineIcon} />

                        <div className="w-px h-4 bg-border/20 mx-1" />

                        {/* Font Style Dropdown */}
                        <div className="relative" ref={fontMenuRef}>
                            <ToolbarButton 
                                onClick={() => setShowFontMenu(!showFontMenu)} 
                                active={false}
                                icon={CaseSensitive} 
                                hasDropdown
                            />
                            {showFontMenu && (
                                <div className="absolute left-0 mt-2 w-48 bg-card border border-border rounded-xl shadow-2xl z-50 p-1">
                                    <DropdownItem onClick={() => { editor.chain().focus().setFontFamily('serif').run(); setShowFontMenu(false); }} icon={Type} label="Serif Style" />
                                    <DropdownItem onClick={() => { editor.chain().focus().setFontFamily('inter').run(); setShowFontMenu(false); }} icon={Type} label="Modern Style" />
                                    <DropdownItem onClick={() => { editor.chain().focus().setFontFamily('monospace').run(); setShowFontMenu(false); }} icon={Type} label="Monospace Style" />
                                    <DropdownItem onClick={() => { editor.chain().focus().setFontFamily('clean').run(); setShowFontMenu(false); }} icon={Type} label="Clean Reading" />
                                </div>
                            )}
                        </div>

                        {/* Highlight Dropdown */}
                        <div className="relative" ref={highlightMenuRef}>
                            <ToolbarButton 
                                onClick={() => setShowHighlightMenu(!showHighlightMenu)} 
                                active={editor.isActive('highlight')}
                                icon={Highlighter} 
                                hasDropdown
                            />
                            {showHighlightMenu && (
                                <div className="absolute left-0 mt-2 w-48 bg-card border border-border rounded-xl shadow-2xl z-50 p-2 grid grid-cols-4 gap-2">
                                    <button onClick={() => { editor.chain().focus().toggleHighlight({ color: '#fef08a' }).run(); setShowHighlightMenu(false); }} className="w-8 h-8 rounded-full bg-yellow-200 border border-yellow-400/20 hover:scale-110 transition-transform" />
                                    <button onClick={() => { editor.chain().focus().toggleHighlight({ color: '#bfdbfe' }).run(); setShowHighlightMenu(false); }} className="w-8 h-8 rounded-full bg-blue-200 border border-blue-400/20 hover:scale-110 transition-transform" />
                                    <button onClick={() => { editor.chain().focus().toggleHighlight({ color: '#fecaca' }).run(); setShowHighlightMenu(false); }} className="w-8 h-8 rounded-full bg-red-200 border border-red-400/20 hover:scale-110 transition-transform" />
                                    <button onClick={() => { editor.chain().focus().toggleHighlight({ color: '#bbf7d0' }).run(); setShowHighlightMenu(false); }} className="w-8 h-8 rounded-full bg-green-200 border border-green-400/20 hover:scale-110 transition-transform" />
                                    <button onClick={() => { editor.chain().focus().unsetHighlight().run(); setShowHighlightMenu(false); }} className="col-span-4 text-[10px] font-bold uppercase tracking-widest text-muted-foreground hover:text-foreground pt-2">Clear Highlight</button>
                                </div>
                            )}
                        </div>

                        <div className="w-px h-4 bg-border/20 mx-1" />

                        <ToolbarButton onClick={() => editor.chain().focus().toggleBulletList().run()} active={editor.isActive('bulletList')} icon={List} />
                        <ToolbarButton onClick={() => editor.chain().focus().toggleOrderedList().run()} active={editor.isActive('orderedList')} icon={ListOrdered} />
                        <ToolbarButton onClick={() => editor.chain().focus().toggleCodeBlock().run()} active={editor.isActive('codeBlock')} icon={Code} />
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* AI Actions */}
                    <div className="relative" ref={aiMenuRef}>
                        <button 
                            onClick={() => setShowAiMenu(!showAiMenu)}
                            disabled={isAiProcessing}
                            className="flex items-center gap-2 px-4 py-2 bg-foreground/5 text-foreground rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-foreground/10 transition-all border border-transparent hover:border-foreground/10"
                        >
                            {isAiProcessing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Sparkles className="w-3.5 h-3.5" />}
                            AI Tools
                        </button>
                        {showAiMenu && (
                            <div className="absolute right-0 mt-2 w-56 bg-card border border-border rounded-2xl shadow-2xl overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-200">
                                <div className="p-2 space-y-1">
                                    <AiMenuItem icon={Type} label="Optimize Title" description="Generate a smart title" onClick={() => handleAiAction('suggest_title')} />
                                    <AiMenuItem icon={AlignLeft} label="Generate Summary" description="3-5 line intelligence brief" onClick={() => handleAiAction('summarize')} />
                                    <AiMenuItem icon={LayoutList} label="Extract Directives" description="Convert to bullet points" onClick={() => handleAiAction('bullet_points')} />
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Download Menu */}
                    <div className="relative" ref={downloadMenuRef}>
                        <button 
                            onClick={() => setShowDownloadMenu(!showDownloadMenu)}
                            className="p-2 hover:bg-foreground/5 rounded-xl transition-all group border border-border/20"
                            title="Download Note"
                        >
                            <Download className="w-4 h-4 text-muted-foreground group-hover:text-foreground" />
                        </button>
                        {showDownloadMenu && (
                            <div className="absolute right-0 mt-2 w-48 bg-card border border-border rounded-xl shadow-2xl z-50 p-1">
                                <DropdownItem onClick={handleDownloadPdf} icon={FileCode} label="Download as PDF" />
                                <DropdownItem onClick={handleDownloadTxt} icon={FileText} label="Download as TXT" />
                            </div>
                        )}
                    </div>

                    <button 
                        onClick={handleManualSave}
                        disabled={isSaving}
                        className="flex items-center gap-2 px-6 py-2 bg-foreground text-background rounded-xl text-[10px] font-black uppercase tracking-widest hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50 shadow-xl shadow-foreground/10"
                    >
                        {isSaving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <><Save className="w-3.5 h-3.5" /> Save Note</>}
                    </button>
                </div>
            </div>

            <div 
                className="flex-1 overflow-y-auto cursor-text"
                onClick={(e) => {
                    // Only focus editor if clicking the empty space, not the title input or other interactive elements
                    if (e.target === e.currentTarget && editor && !editor.isFocused) {
                        editor.commands.focus();
                    }
                }}
            >
                <div className="max-w-[800px] mx-auto px-6 py-16 md:py-24 min-h-full" ref={editorContainerRef}>
                    <div className="mb-12 space-y-4">
                        <div className="flex items-center gap-3">
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-muted-foreground/30">
                                Last sync {formatDate(note.last_edited_at)}
                            </span>
                            {lastSaved && (
                                <div className="flex items-center gap-2 text-[10px] font-bold text-green-500/50 uppercase tracking-widest animate-fade-in">
                                    <CheckCircle2 className="w-3 h-3" /> Sync Complete
                                </div>
                            )}
                        </div>
                        <input 
                            type="text"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            placeholder="Untitled Note"
                            className="w-full text-5xl md:text-6xl font-black tracking-tight bg-transparent outline-none placeholder:text-gray-200 transition-all border-none p-0 focus:ring-0 selection:bg-black/10 text-black"
                        />
                    </div>

                    <EditorContent editor={editor} />
                </div>
            </div>

            {/* Bottom Status */}
            <div className="border-t border-border/30 bg-card/5 px-6 py-3 flex items-center justify-between text-[9px] font-black uppercase tracking-[0.2em] text-muted-foreground/30">
                <div className="flex items-center gap-6">
                    <span>{editor.storage.characterCount?.words?.() || 0} Words</span>
                    <span>{editor.storage.characterCount?.characters?.() || 0} Characters</span>
                </div>
                <div className="flex items-center gap-4">
                    <span className="opacity-50">YT Intelligence v2.0 // Advanced Edition</span>
                </div>
            </div>
        </div>
    );
}

interface ToolbarButtonProps {
    onClick: () => void;
    active: boolean;
    icon: React.ElementType;
    hasDropdown?: boolean;
}

function ToolbarButton({ onClick, active, icon: Icon, hasDropdown }: ToolbarButtonProps) {
    return (
        <button 
            type="button"
            onClick={onClick}
            className={`p-2 rounded-xl transition-all flex items-center gap-1.5 ${active ? "bg-black text-white" : "text-gray-500 hover:bg-gray-100 hover:text-black"}`}
        >
            <Icon className="w-3.5 h-3.5" />
            {hasDropdown && <ChevronDown className="w-2.5 h-2.5 opacity-50" />}
        </button>
    );
}

function DropdownItem({ icon: Icon, label, onClick, active }: { icon: any, label: string, onClick: () => void, active?: boolean }) {
    return (
        <button 
            onClick={onClick}
            className={`w-full flex items-center gap-3 p-2.5 rounded-lg transition-all text-left ${active ? "bg-black text-white" : "hover:bg-gray-50 text-gray-600 hover:text-black"}`}
        >
            <Icon className="w-3.5 h-3.5" />
            <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
        </button>
    );
}

function AiMenuItem({ icon: Icon, label, description, onClick }: { icon: any, label: string, description: string, onClick: () => void }) {
    return (
        <button onClick={onClick} className="w-full flex items-center gap-3 p-3 rounded-xl hover:bg-gray-50 transition-all text-left group">
            <div className="p-2 bg-gray-50 rounded-lg group-hover:bg-black text-black group-hover:text-white transition-all">
                <Icon className="w-3.5 h-3.5" />
            </div>
            <div>
                <div className="text-[10px] font-black uppercase tracking-widest text-black">{label}</div>
                <div className="text-[9px] text-gray-500 font-medium">{description}</div>
            </div>
        </button>
    );
}

"use client";

import React from "react";

import { Pin, Star, Trash2, StickyNote } from "lucide-react";
import { formatDate } from "@/lib/utils";

interface Note {
    id: string;
    user_id: string;
    folder_id: string | null;
    title: string;
    content: Record<string, unknown>; // Content is JSONB from Tiptap
    is_pinned: boolean;
    is_favorite: boolean;
    last_edited_at: string;
    created_at: string;
    updated_at: string;
}

interface NoteListProps {
    notes: Note[];
    viewMode: "grid" | "list";
    onSelectNote: (id: string) => void;
    onDeleteNote: (id: string) => void;
    onTogglePin: (id: string, pinned: boolean) => void;
    onToggleFavorite: (id: string, fav: boolean) => void;
}

/**
 * Helper to extract text from Tiptap JSON content for preview
 */
function extractTextFromContent(content: any): string {
    if (!content) return "";
    if (typeof content === "string") return content;

    // If it's the root doc or an array of nodes
    const nodes = content.content || (Array.isArray(content) ? content : null);
    if (!nodes) {
        // Handle text node
        if (content.type === "text") return content.text || "";
        return "";
    }

    if (Array.isArray(nodes)) {
        return nodes.map(extractTextFromContent).join(" ").trim();
    }

    return "";
}

export default function NoteList({ 
    notes, 
    viewMode, 
    onSelectNote, 
    onDeleteNote,
    onTogglePin,
    onToggleFavorite
}: NoteListProps) {
    if (notes.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="w-16 h-16 rounded-[2rem] bg-foreground/5 border border-border flex items-center justify-center mb-6">
                    <StickyNote className="w-8 h-8 text-foreground/20" />
                </div>
                <h3 className="text-lg font-black uppercase tracking-widest text-foreground/40 mb-2">No notes yet</h3>
                <p className="text-muted-foreground text-sm max-w-xs mx-auto">Create your first note to start building your AI knowledge base.</p>
            </div>
        );
    }

    if (viewMode === "list") {
        return (
