function NavIconItem({ 
    onClick, 
    isActive, 
    isHovered,
    onHoverChange,
    icon: Icon, 
    label 
}: { 
    onClick: () => void, 
    isActive: boolean, 
    isHovered: boolean,
    onHoverChange: (hovered: boolean) => void,
    icon: any, 
    label: string 
}) {
    // Determine the current pill position (hover takes priority)
    const isShowingPill = isHovered || (isActive && !isHovered);

    return (
        <div 
            onClick={onClick}
            onMouseEnter={() => onHoverChange(true)}
            onMouseLeave={() => onHoverChange(false)}
            className={cn(
                "relative cursor-pointer group flex items-center justify-center w-11 h-11 transition-all duration-300",
                isActive && "is-active"
            )}
            title={label}
        >
            {/* Active/Hover Pill - The "White Box" */}
            {isShowingPill && (
                <motion.div 
                    layoutId="active-pill"
                    className={cn(
                        "absolute inset-0 rounded-xl transition-all duration-500 ease-in-out z-0",
                        // Default (Bar is Black): Highlight is White (box)
                        "bg-white",
                        // Bar Hover (Bar is White): Highlight is Black (box)
                        "group-hover/nav:bg-black"
                    )}
                    initial={false}
                    transition={{ type: "spring", bounce: 0.3, duration: 0.6 }}
                />
            )}

            <Icon className={cn(
                "w-5 h-5 transition-all duration-300 relative z-10",
                // Base: Icons are white-ish on black bar
                "text-white/40",

                // When "Selected" (Pill is active):
                // On Black Bar (default) -> Icon is Black (on White pill)
                // On White Bar (hover) -> Icon is White (on Black pill)
                isShowingPill 
                    ? "text-black group-hover/nav:text-white" 
                    : "group-hover/nav:text-black/30",

                // Specific item hover triggers full color
                isHovered && !isShowingPill && "text-white",

                // Scale effect
                isHovered && "scale-110"
            )} />
        </div>
    );
}

