"use client";

import { useState, useEffect } from "react";
import { createClient } from "@/lib/supabase/client";
import { Plus, Search, Filter, Grid, List as ListIcon, Cloud } from "lucide-react";
import NoteList from "./NoteList";
import NoteNavigation from "./NoteNavigation";
import NoteEditor from "./NoteEditor";
import toast from "react-hot-toast";
import { X } from "lucide-react";

export interface Note {
    id: string;
    user_id: string;
    folder_id: string | null;
    title: string;
    content: Record<string, unknown>; // Content is JSONB from Tiptap
    is_pinned: boolean;
    is_favorite: boolean;
    last_edited_at: string;
    created_at: string;
    updated_at: string;
    tags?: { id: string; name: string; color: string }[];
}

interface Folder {
    id: string;
    name: string;
    count?: number;
}

interface Tag {
    id: string;
    name: string;
    color: string;
    count?: number;
}

interface NotesClientProps {
    initialUser: {
        id: string;
        email?: string;
    };
}

export default function NotesClient({ initialUser }: NotesClientProps) {
    const [notes, setNotes] = useState<Note[]>([]);
    const [folders, setFolders] = useState<Folder[]>([]);
    const [tags, setTags] = useState<Tag[]>([]);
    const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null);
    const [selectedFilter, setSelectedFilter] = useState<{ type: 'all' | 'favorites' | 'pinned' | 'folder' | 'tag', id?: string }>({ type: 'all' });
    const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
    const [searchQuery, setSearchQuery] = useState("");
    const [loading, setLoading] = useState(true);
    const [needsSetup, setNeedsSetup] = useState(false);
    const [showFolderModal, setShowFolderModal] = useState(false);
    const [showTagModal, setShowTagModal] = useState(false);
    const [newItemName, setNewItemName] = useState("");
    const [newItemColor, setNewItemColor] = useState("#999999");

    const supabase = createClient();

    const fetchData = async () => {
        setLoading(prev => prev ? prev : true);
        try {
            // Fetch Notes
            const { data: notesData, error: notesError } = await supabase
                .from("notes")
                .select(`
                    *,
                    note_tags(
                        tags(*)
                    )
                `)
                .order("is_pinned", { ascending: false })
                .order("updated_at", { ascending: false });

            if (notesError) throw notesError;

            // Fetch Folders
            const { data: foldersData, error: foldersError } = await supabase
                .from("folders")
                .select("*")
                .order("name");

            if (foldersError && foldersError.code !== '42P01') throw foldersError;

            // Fetch Tags
            const { data: tagsData, error: tagsError } = await supabase
                .from("tags")
                .select("*")
                .order("name");

            if (tagsError && tagsError.code !== '42P01') throw tagsError;

            // Transform notes to include flattened tags
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const processedNotes = (notesData || []).map((note: any) => ({
                ...note,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                tags: note.note_tags?.map((nt: any) => nt.tags).filter(Boolean) || []
            }));

            setNotes(processedNotes);
            setFolders(foldersData || []);
            setTags(tagsData || []);
            setNeedsSetup(false);
        } catch (error: any) {
            console.error("Error fetching data:", error);
            const msg = error.message || String(error);
            if (msg.includes("Failed to fetch") || msg.toLowerCase().includes("network")) {
                toast.error("Network Error: Could not connect to Supabase. Check your URL and connection.");
            } else if (error.code === '42P01' || msg.includes("public.notes")) {
                setNeedsSetup(true);
            } else {
                toast.error(`Database error: ${msg}`);
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const handleCreateNote = async () => {
        const newNote = {
            user_id: initialUser.id,
            title: "Untitled Note",
            content: { type: "doc", content: [] },
            last_edited_at: new Date().toISOString(),
        };

        const { data, error } = await supabase
            .from("notes")
            .insert(newNote)
            .select()
            .single();

        if (error) {
            console.error("Error creating note:", error);
            if (error.code === '42P01') {
                setNeedsSetup(true);
            } else {
                toast.error("Failed to create note. Did you run the SQL schema?");
            }
        } else {
            setNotes([data, ...notes]);
            setSelectedNoteId(data.id);
            toast.success("New note created!");
        }
    };

    const handleUpdateNote = async (id: string, updates: Partial<Note>) => {
        const { error } = await supabase
            .from("notes")
            .update({ ...updates, updated_at: new Date().toISOString() })
            .eq("id", id);

        if (error) {
            console.error("Error updating note:", error);
        } else {
            setNotes(notes.map(n => n.id === id ? { ...n, ...updates } : n));
        }
    };

    const handleDeleteNote = async (id: string) => {
        const { error } = await supabase
            .from("notes")
            .delete()
            .eq("id", id);

        if (error) {
            console.error("Error deleting note:", error);
            toast.error("Failed to delete note.");
        } else {
            setNotes(notes.filter(n => n.id !== id));
            if (selectedNoteId === id) setSelectedNoteId(null);
            toast.success("Note deleted.");
        }
    };

    const counts = {
        all: notes.length,
        favorites: notes.filter(n => n.is_favorite).length,
        pinned: notes.filter(n => n.is_pinned).length,
        folders: folders.map(f => ({
            id: f.id,
            count: notes.filter(n => n.folder_id === f.id).length
        })),
        tags: tags.map(t => ({
            id: t.id,
            count: notes.filter(n => n.tags?.some(tag => tag.id === t.id)).length
        }))
    };

    const filteredNotes = notes.filter(note => {
        const matchesSearch = note.title.toLowerCase().includes(searchQuery.toLowerCase());
        if (!matchesSearch) return false;

        switch (selectedFilter.type) {
            case 'favorites': return note.is_favorite;
            case 'pinned': return note.is_pinned;
            case 'folder': return note.folder_id === selectedFilter.id;
            case 'tag': return note.tags?.some(t => t.id === selectedFilter.id);
            default: return true;
        }
    });

    const handleCreateFolder = async (name: string) => {
        const { data, error } = await supabase
            .from("folders")
            .insert({ name, user_id: initialUser.id })
            .select()
            .single();

        if (error) {
            toast.error("Failed to create folder");
        } else {
            setFolders([...folders, data]);
            toast.success("Folder created!");
        }
    };

    const handleCreateTag = async (name: string, color: string) => {
        const { data, error } = await supabase
            .from("tags")
            .insert({ name, color, user_id: initialUser.id })
            .select()
            .single();

        if (error) {
            toast.error("Failed to create tag");
        } else {
            setTags([...tags, data]);
            toast.success("Tag created!");
        }
    };

    const selectedNote = notes.find(n => n.id === selectedNoteId);

    if (needsSetup) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center p-8 text-center bg-background overflow-y-auto">
                <div className="w-20 h-20 rounded-[2.5rem] bg-foreground/5 border border-border flex items-center justify-center mb-8 shrink-0">
                    <Cloud className="w-10 h-10 text-foreground/20" />
                </div>
                <h2 className="text-3xl font-black uppercase tracking-tight mb-4">Database Setup Required</h2>
                <p className="text-muted-foreground text-sm max-w-md mb-8 leading-relaxed">
                    The notes table is missing from your Supabase database. Please run the following SQL in your <span className="text-foreground font-bold">Supabase SQL Editor</span> to initialize the database.
                </p>

                <div className="w-full max-w-2xl bg-card border border-border rounded-2xl p-6 mb-8 text-left overflow-hidden">
                    <div className="flex items-center justify-between mb-4">
                        <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">SQL Migration Script</span>
                        <button 
                            suppressHydrationWarning
                            onClick={() => {
                                navigator.clipboard.writeText(`-- 1. Create the notes table
CREATE TABLE IF NOT EXISTS public.notes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    folder_id UUID DEFAULT NULL,
    title TEXT NOT NULL DEFAULT 'Untitled Note',
    content JSONB DEFAULT '{"type": "doc", "content": []}',
    is_pinned BOOLEAN DEFAULT FALSE,
    is_favorite BOOLEAN DEFAULT FALSE,
    last_edited_at TIMESTAMPTZ DEFAULT NOW(),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Create folders table
CREATE TABLE IF NOT EXISTS public.folders (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Create tags table
CREATE TABLE IF NOT EXISTS public.tags (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    color TEXT DEFAULT '#999999',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(user_id, name)
);

-- 4. Create junction table for note-tags
CREATE TABLE IF NOT EXISTS public.note_tags (
    note_id UUID REFERENCES public.notes(id) ON DELETE CASCADE,
    tag_id UUID REFERENCES public.tags(id) ON DELETE CASCADE,
    PRIMARY KEY (note_id, tag_id)
);

-- 5. Enable RLS
ALTER TABLE public.notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.folders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.note_tags ENABLE ROW LEVEL SECURITY;

-- 6. RLS Policies
CREATE POLICY "Users access own notes" ON public.notes FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users access own folders" ON public.folders FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users access own tags" ON public.tags FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users access own note_tags" ON public.note_tags FOR ALL USING (
    EXISTS (SELECT 1 FROM public.notes WHERE id = note_id AND user_id = auth.uid())
);

-- 7. Trigger for updated_at
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_notes_updated_at BEFORE UPDATE ON public.notes FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();
CREATE TRIGGER update_folders_updated_at BEFORE UPDATE ON public.folders FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();
CREATE TRIGGER update_tags_updated_at BEFORE UPDATE ON public.tags FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();`);
                                toast.success("SQL copied to clipboard!");
                            }}
                            className="text-[10px] font-black uppercase tracking-widest text-foreground hover:opacity-70 transition-opacity"
                        >
                            Copy Code
                        </button>
                    </div>
                    <pre className="text-[11px] font-mono text-muted-foreground overflow-x-auto p-4 bg-muted/30 rounded-xl leading-relaxed">
{`-- Run this in Supabase SQL Editor:
-- 1. Create tables (Notes, Folders, Tags, Note_Tags)
-- 2. Enable RLS and add policies
-- 3. Add auto-update triggers`}
                    </pre>
                </div>

                <div className="flex flex-col gap-4 w-full max-w-sm">
                    <button 
                        suppressHydrationWarning
                        onClick={() => window.location.reload()}
                        className="bg-foreground text-background px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-xs hover:scale-105 transition-all shadow-2xl active:scale-95"
                    >
                        Refreshing Connection
                    </button>
                    <a 
                        href="https://supabase.com/dashboard" 
                        target="_blank" 
                        rel="noreferrer"
                        className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/60 hover:text-foreground transition-colors"
                    >
                        Go to Supabase Dashboard →
                    </a>
                </div>
            </div>
        );
    }

    return (
        <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-background text-foreground flex-col relative">
            {/* Note Navigation Dock */}
            {!selectedNoteId && (
                <NoteNavigation 
                    folders={folders.map(f => ({ ...f, count: counts.folders.find(cf => cf.id === f.id)?.count || 0 }))}
                    tags={tags.map(t => ({ ...t, count: counts.tags.find(ct => ct.id === t.id)?.count || 0 }))}
                    counts={{
                        all: counts.all,
                        favorites: counts.favorites,
                        pinned: counts.pinned
                    }}
                    notes={notes}
                    selectedFilter={selectedFilter}
                    onSelectFilter={setSelectedFilter}
                    onAddFolder={() => setShowFolderModal(true)}
                    onAddTag={() => setShowTagModal(true)}
                />
            )}

            {/* Main Content */}
            <main className="flex-1 flex flex-col min-w-0">
                {selectedNote ? (
                    <NoteEditor 
                        key={selectedNote.id}
                        note={selectedNote} 
                        onSave={(updates: Partial<Note>) => handleUpdateNote(selectedNote.id, updates)}
                        onBack={() => setSelectedNoteId(null)}
                    />
                ) : (
                    <div className="flex-1 flex flex-col overflow-hidden">
                        {/* Header */}
                        <div className="p-8 pb-4">
                            <div className="flex items-center justify-between mb-8">
                                <div>
                                    <div className="flex items-center gap-2 mb-2">
                                        <Cloud className="w-4 h-4 text-muted-foreground/40" />
                                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground">My Knowledge Base</span>
                                    </div>
                                    <h1 className="text-4xl font-black tracking-tight">Cloud Notes</h1>
                                </div>
                                <button 
                                    suppressHydrationWarning
                                    onClick={handleCreateNote}
                                    className="bg-foreground text-background px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[10px] flex items-center gap-3 hover:scale-105 transition-all shadow-2xl active:scale-95"
                                >
                                    <Plus className="w-4 h-4" /> New Note
                                </button>
                            </div>

                            {/* Search & Tool Bar */}
                            <div className="flex items-center gap-4 mb-4">
                                <div className="flex-1 relative">
                                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                                    <input 
                                        suppressHydrationWarning
                                        type="text" 
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        placeholder="Search notes..." 
                                        className="w-full bg-card border border-border rounded-xl pl-12 pr-4 py-3 text-sm font-medium focus:border-foreground outline-none transition-all"
                                    />
                                </div>
                                <div className="flex items-center bg-card border border-border rounded-xl p-1">
                                    <button 
                                        suppressHydrationWarning
                                        onClick={() => setViewMode("grid")}
                                        className={`p-2 rounded-lg transition-all ${viewMode === "grid" ? "bg-foreground text-background shadow-md" : "text-muted-foreground hover:bg-muted"}`}
                                    >
                                        <Grid className="w-4 h-4" />
                                    </button>
                                    <button 
                                        suppressHydrationWarning
                                        onClick={() => setViewMode("list")}
                                        className={`p-2 rounded-lg transition-all ${viewMode === "list" ? "bg-foreground text-background shadow-md" : "text-muted-foreground hover:bg-muted"}`}
                                    >
                                        <ListIcon className="w-4 h-4" />
                                    </button>
                                </div>
                                <button 
                                    suppressHydrationWarning
                                    className="bg-card border border-border p-3 rounded-xl hover:border-foreground transition-all"
                                >
                                    <Filter className="w-4 h-4" />
                                </button>
                            </div>
                        </div>

                        {/* Note List Container */}
                        <div className="flex-1 overflow-y-auto p-8 pt-0">
                            {loading ? (
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                    {[1, 2, 3].map(i => (
                                        <div key={i} className="bg-card border border-border rounded-[2rem] p-8 animate-pulse h-48"></div>
                                    ))}
                                </div>
                            ) : (
                                <NoteList 
                                    notes={filteredNotes} 
                                    viewMode={viewMode}
                                    onSelectNote={setSelectedNoteId}
                                    onDeleteNote={handleDeleteNote}
                                    onTogglePin={(id: string, pinned: boolean) => handleUpdateNote(id, { is_pinned: pinned })}
                                    onToggleFavorite={(id: string, fav: boolean) => handleUpdateNote(id, { is_favorite: fav })}
                                />
                            )}
                        </div>
                    </div>
                )}
            </main>
            {/* Modals */}
            {showFolderModal && (
                <Modal title="Initialize Module" onClose={() => setShowFolderModal(false)} onSubmit={(e) => {
                    e.preventDefault();
                    if (newItemName.trim()) {
                        handleCreateFolder(newItemName.trim());
                        setNewItemName("");
                        setShowFolderModal(false);
                    }
                }}>
                    <input autoFocus type="text" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} placeholder="Folder Name" className="w-full bg-muted border border-border rounded-xl px-4 py-3 text-sm font-medium outline-none focus:border-foreground transition-all mb-6" />
                    <div className="flex gap-4">
                        <button type="button" onClick={() => setShowFolderModal(false)} className="flex-1 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground hover:text-foreground">Cancel</button>
                        <button type="submit" className="flex-1 bg-foreground text-background py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:scale-105 shadow-xl">Create</button>
                    </div>
                </Modal>
            )}

            {showTagModal && (
                <Modal title="New Directive" onClose={() => setShowTagModal(false)} onSubmit={(e) => {
                    e.preventDefault();
                    if (newItemName.trim()) {
                        handleCreateTag(newItemName.trim(), newItemColor);
                        setNewItemName("");
                        setShowTagModal(false);
                    }
                }}>
                    <div className="space-y-6">
                        <input autoFocus type="text" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} placeholder="Tag Name" className="w-full bg-muted border border-border rounded-xl px-4 py-3 text-sm font-medium outline-none focus:border-foreground transition-all" />
                        <div className="flex items-center justify-between px-2">
                             <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Select Color</span>
                             <input type="color" value={newItemColor} onChange={(e) => setNewItemColor(e.target.value)} className="w-8 h-8 rounded-lg overflow-hidden border-none bg-transparent cursor-pointer" />
                        </div>
                        <div className="flex gap-4">
                            <button type="button" onClick={() => setShowTagModal(false)} className="flex-1 py-3 text-[10px] font-black uppercase tracking-widest text-muted-foreground hover:text-foreground">Cancel</button>
                            <button type="submit" className="flex-1 bg-foreground text-background py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:scale-105 shadow-xl">Create</button>
                        </div>
                    </div>
                </Modal>
            )}
        </div>
    );
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function Modal({ title, children, onClose, onSubmit }: { title: string, children: React.ReactNode, onClose: () => void, onSubmit: (e: React.FormEvent) => void }) {
    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-background/80 backdrop-blur-xl">
            <div className="w-full max-w-sm bg-card border border-border rounded-[2.5rem] shadow-2xl overflow-hidden">
                <div className="p-8 border-b border-border/50 flex items-center justify-between">
                    <h3 className="text-sm font-black uppercase tracking-[0.3em] text-foreground">{title}</h3>
                    <button onClick={onClose} className="p-2 hover:bg-muted rounded-xl transition-all"><X className="w-4 h-4" /></button>
                </div>
                <form onSubmit={onSubmit} className="p-8">{children}</form>
            </div>
        </div>
    );
}

"use client";
import React from "react";
import { motion } from "framer-motion";
import Link from "next/link";
import Image from "next/image";
import { cn } from "@/lib/utils";

const transition: any = {
  type: "spring",
  mass: 0.5,
  damping: 11.5,
  stiffness: 100,
  restDelta: 0.001,
  restSpeed: 0.001,
};

export const MenuItem = ({
  setActive,
  active,
  item,
  children,
  orientation = "horizontal",
  placement = "bottom",
  itemClassName,
  trigger,
}: {
  setActive: (item: string) => void;
  active: string | null;
  item: string;
  children?: React.ReactNode;
  orientation?: "horizontal" | "vertical";
  placement?: "top" | "bottom";
  itemClassName?: string;
  trigger?: React.ReactNode;
}) => {
  return (
    <div onMouseEnter={() => setActive(item)} className="relative ">
      <motion.div
        transition={{ duration: 0.3 }}
        className={cn(
          "cursor-pointer hover:opacity-[0.9]",
          itemClassName
        )}
      >
        {trigger || item}
      </motion.div>
      {active !== null && (
        <motion.div
          initial={{ 
            opacity: 0, 
            scale: 0.85, 
            y: orientation === "horizontal" ? (placement === "top" ? -10 : 10) : 0, 
            x: orientation === "vertical" ? 10 : 0 
          }}
          animate={{ opacity: 1, scale: 1, y: 0, x: 0 }}
          transition={transition}
        >
          {active === item && (
            <div className={cn(
              "absolute",
              orientation === "horizontal" 
                ? cn(
                    "left-1/2 transform -translate-x-1/2",
                    placement === "top" ? "bottom-[calc(100%_+_1.2rem)] pb-4" : "top-[calc(100%_+_1.2rem)] pt-4"
                  )
                : "left-full top-0 ml-4 pt-4"
            )}>
              <motion.div
                transition={transition}
                layoutId="active"
                className="bg-white/95 backdrop-blur-md rounded-2xl overflow-hidden border border-gray-200 shadow-2xl"
              >
                <motion.div
                  layout // layout ensures smooth animation of children
                  className="w-max h-full p-4"
                >
                  {children}
                </motion.div>
              </motion.div>
            </div>
          )}
        </motion.div>
      )}
    </div>
  );
};

export const Menu = ({
  setActive,
  children,
  className,
}: {
  setActive: (item: string | null) => void;
  children: React.ReactNode;
  className?: string;
}) => {
  return (
    <nav
      onMouseLeave={() => setActive(null)} // resets the state
      className={cn(
        "relative rounded-full border border-transparent dark:bg-black dark:border-white/[0.2] bg-white shadow-input flex justify-center space-x-4 px-8 py-6",
        className
      )}
    >
      {children}
    </nav>
  );
};

